using System.Text;
using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public class AssessmentNoticeTests
{
    static readonly EntityId Actor=ContractFixture.Officer,Lord=ContractFixture.Lord,N1=new("message:notice1"),N2=new("message:notice2");
    static EntityId TaskId(WorldSession s)=>s.DiagnosticSnapshot().Tasks.Single().Id;
    static WorldSession Sent(){var s=new WorldSession(AssessmentNotice.Create());s.Submit(IncomingMission.Build(s.DiagnosticSnapshot(),"request:notice",false),s.Revision);return s;}
    static void OpenOrder(WorldSession s){s.AdvanceTo(1);s.Open(Actor,IncomingMission.View(s,Actor).Single().Message,s.Revision);s.SetPaused(false);}
    static WorldSession Ready(){var s=Sent();OpenOrder(s);s.AdvanceTo(2);s.InterruptMission(TaskId(s),Actor,s.Revision);s.AdvanceTo(7);return s;}
    static void Publish(WorldSession s,EntityId id){Assert.Equal(ResultCode.Accepted,s.PublishAssessment(id,TaskId(s),Lord,s.Revision).Code);}
    static void OpenNotice(WorldSession s,EntityId id){Assert.Equal(ResultCode.Accepted,s.Open(Actor,id,s.Revision).Code);s.SetPaused(false);}
    static AssessmentNotice.Payload Payload(WorldSession s,EntityId id)=>ContractJson.Read<AssessmentNotice.Payload>(Encoding.UTF8.GetBytes(s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==id.Value).Body));
    static void Explain(WorldSession s){s.ExplainMission(TaskId(s),Actor,MissionReview.Explanation.ClaimedDanger,s.Revision);}
    [Fact] public void UnrecognizedOutcomeCannotBePublished(){var s=Sent();OpenOrder(s);Assert.Equal(ResultCode.NotAvailable,s.PublishAssessment(N1,TaskId(s),Lord,s.Revision).Code);Assert.Empty(AssessmentNotice.Inbox(s,Actor));}
    [Fact] public void WrongAssessorCannotPublish(){var s=Ready();var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.PublishAssessment(N1,TaskId(s),Actor,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void MissingAuthorityCannotPublish(){var s=Ready();var w=s.DiagnosticSnapshot();w.Grants=w.Grants.Where(g=>g.Agent!=Lord).ToArray();s=new(w);Assert.Equal(ResultCode.NotAvailable,s.PublishAssessment(N1,TaskId(s),Lord,s.Revision).Code);}
    [Fact] public void StalePublicationDoesNotSend(){var s=Ready();Assert.Equal(ResultCode.StateChanged,s.PublishAssessment(N1,TaskId(s),Lord,s.Revision-1).Code);Assert.DoesNotContain(s.DiagnosticSnapshot().Messaging.Messages,m=>m.Kind==AssessmentNotice.Kind);}
    [Fact] public void ContentAndVersionAreHiddenUntilOpening(){var s=Ready();Publish(s,N1);Assert.Empty(AssessmentNotice.Inbox(s,Actor));s.AdvanceTo(8);Assert.True(s.Paused);var c=Assert.Single(AssessmentNotice.Inbox(s,Actor));Assert.Null(c.Known);Assert.True(c.CanOpen);Assert.Empty(AssessmentNotice.LatestKnown(s,Actor));OpenNotice(s,N1);Assert.Equal(1,AssessmentNotice.LatestKnown(s,Actor).Single().Version);}
    [Fact] public void PublicationRetriesDoNotRewriteSnapshot(){var s=Ready();Publish(s,N1);string original=s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==N1.Value).Body;s.AdvanceTo(8);s.SetPaused(false);Explain(s);s.AdvanceTo(9);Assert.Equal(ResultCode.AlreadyAccepted,s.PublishAssessment(N1,TaskId(s),Lord,s.Revision).Code);Assert.Equal(original,s.DiagnosticSnapshot().Messaging.Messages.Single(m=>m.Id==N1.Value).Body);Assert.Contains("未認識",Payload(s,N1).Review.Reason);}
    [Fact] public void NoNewEvidenceDoesNotCreateMeaninglessRevision(){var s=Ready();Publish(s,N1);Assert.Equal(ResultCode.NotAvailable,s.PublishAssessment(N2,TaskId(s),Lord,s.Revision).Code);Assert.Single(s.DiagnosticSnapshot().Messaging.Messages,m=>m.Kind==AssessmentNotice.Kind);}
    [Fact] public void NewReasonProducesImmutableRevisionWithParent(){var s=Ready();Publish(s,N1);s.AdvanceTo(8);OpenNotice(s,N1);s.AdvanceTo(10);Explain(s);s.AdvanceTo(11);Publish(s,N2);var p=Payload(s,N2);Assert.Equal(2,p.Version);Assert.Equal(N1,p.Supersedes);Assert.Contains("事実は未確認",p.Review.Reason);Assert.Contains("未認識",Payload(s,N1).Review.Reason);Assert.Equal(1,AssessmentNotice.LatestKnown(s,Actor).Single().Version);}
    [Fact] public void ReplyRequiresPrincipalAndOpening(){var s=Ready();Publish(s,N1);Assert.Equal(ResultCode.NotAvailable,s.RespondAssessment(N1,Actor,AssessmentNotice.Reply.Received,s.Revision).Code);s.AdvanceTo(8);Assert.Equal(ResultCode.NotAvailable,s.RespondAssessment(N1,Actor,AssessmentNotice.Reply.Received,s.Revision).Code);OpenNotice(s,N1);Assert.Equal(ResultCode.NotAvailable,s.RespondAssessment(N1,ContractFixture.Clerk,AssessmentNotice.Reply.Received,s.Revision).Code);}
    [Theory][InlineData(AssessmentNotice.Reply.Received)][InlineData(AssessmentNotice.Reply.RequestReview)] public void ReplyTravelsAndDoesNotInstantlyReachAssessor(AssessmentNotice.Reply reply){var s=Ready();Publish(s,N1);s.AdvanceTo(8);OpenNotice(s,N1);Assert.Equal(ResultCode.Accepted,s.RespondAssessment(N1,Actor,reply,s.Revision).Code);Assert.Empty(AssessmentNotice.KnownResponses(s,Lord));s.AdvanceTo(9);Assert.Equal(reply,AssessmentNotice.KnownResponses(s,Lord).Single().Reply);Assert.Equal("責任・処分は未審査",AssessmentNotice.LatestKnown(s,Actor).Single().Review.Liability);}
    [Fact] public void ReplyRetriesAndChangedPayloadAreAtomic(){var s=Ready();Publish(s,N1);s.AdvanceTo(8);OpenNotice(s,N1);s.RespondAssessment(N1,Actor,AssessmentNotice.Reply.Received,s.Revision);var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.RespondAssessment(N1,Actor,AssessmentNotice.Reply.Received,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.RespondAssessment(N1,Actor,AssessmentNotice.Reply.RequestReview,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.RespondAssessment(N1,Actor,(AssessmentNotice.Reply)10,s.Revision).Code);Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void StaleReplyCannotSend(){var s=Ready();Publish(s,N1);s.AdvanceTo(8);OpenNotice(s,N1);Assert.Equal(ResultCode.StateChanged,s.RespondAssessment(N1,Actor,AssessmentNotice.Reply.Received,s.Revision-1).Code);Assert.Empty(AssessmentNotice.KnownResponses(s,Lord));}
    [Fact] public void NoticeAndReplyReadsDoNotMutateWorld(){var s=Ready();Publish(s,N1);s.AdvanceTo(8);OpenNotice(s,N1);var hash=ContractJson.CanonicalHash(s.DiagnosticSnapshot());for(int i=0;i<5;i++){AssessmentNotice.Inbox(s,Actor);AssessmentNotice.LatestKnown(s,Actor);AssessmentNotice.KnownResponses(s,Lord);}Assert.Equal(hash,ContractJson.CanonicalHash(s.DiagnosticSnapshot()));}
    [Fact] public void UnrelatedActorDoesNotLearnNoticeOrResponse(){var s=Ready();Publish(s,N1);s.AdvanceTo(8);OpenNotice(s,N1);s.RespondAssessment(N1,Actor,AssessmentNotice.Reply.Received,s.Revision);s.AdvanceTo(9);Assert.Empty(AssessmentNotice.Inbox(s,ContractFixture.Clerk));Assert.Empty(AssessmentNotice.KnownResponses(s,ContractFixture.Clerk));}
    [Fact] public void CollidingMessageIdIsRejected(){var s=Ready();var id=new EntityId(s.DiagnosticSnapshot().Messaging.Messages.First().Id);Assert.Equal(ResultCode.IdPayloadConflict,s.PublishAssessment(id,TaskId(s),Lord,s.Revision).Code);}
    [Fact] public void PhysicallyRetriedOlderNoticeCannotRollBackNewerKnownVersion(){var s=Ready();Publish(s,N1);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,N1.Value));s.AdvanceTo(10);Explain(s);s.AdvanceTo(11);Publish(s,N2);s.AdvanceTo(12);OpenNotice(s,N2);s.AdvanceTo(14);s.DiagnosticTransport((m,t)=>MessageFlow.Retry(m,N1.Value,Lord.Value,t));s.AdvanceTo(15);Assert.Equal(2,AssessmentNotice.LatestKnown(s,Actor).Single().Version);OpenNotice(s,N1);Assert.Equal(2,AssessmentNotice.LatestKnown(s,Actor).Single().Version);Assert.Equal(2,AssessmentNotice.Inbox(s,Actor).Length);}
    [Theory][InlineData(true)][InlineData(false)] public void InvalidSavedRevisionOrClaimIsRejected(bool version){var s=Ready();Publish(s,N1);var w=s.DiagnosticSnapshot();var p=Payload(s,N1);p=version?p with{Version=9}:p with{Review=p.Review with{Reason="未受領の秘密"}};w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==N1.Value?m with{Body=Encoding.UTF8.GetString(ContractJson.Write(p))}:m).ToArray();Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact] public void TamperedResponseBeforeOpeningIsRejected(){var s=Ready();Publish(s,N1);Assert.Throws<InvalidDataException>(()=>s.DiagnosticTransport((m,t)=>MessageFlow.Send(m,new("message:forged",s.DiagnosticSnapshot().Requests.Single().Id.Value,AssessmentNotice.ResponseKind,Actor.Value,Lord.Value,Encoding.UTF8.GetString(ContractJson.Write(new AssessmentNotice.Response(N1,AssessmentNotice.Reply.Received))),ContractFixture.Castle.Value,t),t,1)));}
    [Theory][InlineData(7)][InlineData(8)][InlineData(12)][InlineData(18)] public void SaveRestorePreservesNoticeRevisionsAndReplies(int at){var s=Sent();Timeline(s,at);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"notice-"+Guid.NewGuid().ToString("N")),w.Definitions);store.Save(s,"stage",w.WorldId,new(0,10));var h=new WorldSessionHost(new(AssessmentNotice.Create()));Assert.Equal(ResultCode.Accepted,h.CommitLoad(store.Prepare("stage"),h.Current,h.Current.Revision));Assert.Equal(ContractJson.Write(AssessmentNotice.Inbox(s,Actor)),ContractJson.Write(AssessmentNotice.Inbox(h.Current,Actor)));Timeline(s,20);Timeline(h.Current,20);Assert.Equal(ContractJson.Write(AssessmentNotice.LatestKnown(s,Actor)),ContractJson.Write(AssessmentNotice.LatestKnown(h.Current,Actor)));Assert.Equal(ContractJson.Write(AssessmentNotice.KnownResponses(s,Lord)),ContractJson.Write(AssessmentNotice.KnownResponses(h.Current,Lord)));Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot().Messaging.Messages),ContractJson.Write(h.Current.DiagnosticSnapshot().Messaging.Messages));}
    static void Timeline(WorldSession s,long target){foreach(var at in new long[]{1,2,7,8,9,10,11,12,13,14}.Where(t=>s.Seconds<t&&t<=target)){s.SetPaused(false);s.AdvanceTo(at);if(at==1){s.Open(Actor,IncomingMission.View(s,Actor).Single().Message,s.Revision);s.SetPaused(false);}if(at==2)s.InterruptMission(TaskId(s),Actor,s.Revision);if(at==7)Publish(s,N1);if(at==9)OpenNotice(s,N1);if(at==10)Explain(s);if(at==12)Publish(s,N2);if(at==14){OpenNotice(s,N2);s.RespondAssessment(N2,Actor,AssessmentNotice.Reply.RequestReview,s.Revision);}}s.SetPaused(false);s.AdvanceTo(target);}
    [Fact] public void PreviousProfileDoesNotAcquireNewNotificationRules(){var s=new WorldSession(MissionReview.Create());s.Submit(IncomingMission.Build(s.DiagnosticSnapshot(),"request:old",false),s.Revision);Assert.Equal(ResultCode.NotAvailable,s.PublishAssessment(N1,TaskId(s),Lord,s.Revision).Code);Assert.NotEqual(s.DiagnosticSnapshot().Definitions.Version,AssessmentNotice.Create().Definitions.Version);}
}
